import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"噬嗑","description":"焦氏易林注 - 噬嗑","frontmatter":{"title":"噬嗑","description":"焦氏易林注 - 噬嗑"},"headers":[],"relativePath":"classics/jiaoyilin/021.md","filePath":"classics/jiaoyilin/021.md"}'),l={name:"classics/jiaoyilin/021.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="噬嗑" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑" aria-label="Permalink to “噬嗑”">​</a></h1><h3 id="噬嗑-1" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑-1" aria-label="Permalink to “噬嗑”">​</a></h3><h3 id="噬嗑之乾" tabindex="-1">噬嗑之乾 <a class="header-anchor" href="#噬嗑之乾" aria-label="Permalink to “噬嗑之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>北風相牽，提笑語言。伯歌叔舞，燕樂以喜。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《損》。此全用遇卦《噬嗑》象，不及之卦。</p><h3 id="噬嗑之坤" tabindex="-1">噬嗑之坤 <a class="header-anchor" href="#噬嗑之坤" aria-label="Permalink to “噬嗑之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>甲戊己庚，隨時運行。不失常節，鹹逢出生。各樂其類，達性任情。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此亦全用《噬嗑》象。坎納戊，離己震庚，震，東方木，故曰甲戊己庚。艮為時，震為運行、為出生、為樂，蓋《噬嗑》震春離夏坎冬，伏兌為秋，四時俱備，故林雲爾。○五六句宋元本倒置，今依汲古。</p><h3 id="噬嗑之屯" tabindex="-1">噬嗑之屯 <a class="header-anchor" href="#噬嗑之屯" aria-label="Permalink to “噬嗑之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>破亡之虛，神祇哀憂。進往無光，留止有慶。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎為破，坤為亡、為虛，虛墟同。震為神，坤為地，故曰神祇。祇，地神也。坎為憂，震為進，坎隱故無光。艮止故有慶。○神祇哀憂，汲古作神所憂衰，依宋元本。</p><h3 id="噬嗑之蒙" tabindex="-1">噬嗑之蒙 <a class="header-anchor" href="#噬嗑之蒙" aria-label="Permalink to “噬嗑之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>註斯膏澤，捍衛百毒。防以江南，虺不能螫。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坎為膏澤、為註，艮守為捍衛。坤坎皆為毒，故曰百毒。艮為防，坤為江河，震為南，坎為虺、為螫。○捍，汲古作祈，依宋元本。</p><h3 id="噬嗑之需" tabindex="-1">噬嗑之需 <a class="header-anchor" href="#噬嗑之需" aria-label="Permalink to “噬嗑之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>日月相望，光明盛昌。三聖茂功，仁德大隆。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎月離日，坎西離東，故曰相望。離為光明，坎為聖，離卦數三，故曰三聖，謂文、武、周公也。乾為功、為德、為大、為隆。○隆，汲古訛降，茂作成，依宋元本。</p><h3 id="噬嗑之訟" tabindex="-1">噬嗑之訟 <a class="header-anchor" href="#噬嗑之訟" aria-label="Permalink to “噬嗑之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>大蛇巨魚，戰於國郊。上下隔塞，衛侯廬漕。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>《左傳莊十四年》&quot;內蛇與外蛇鬥於鄭南門&quot;，中互巽為蛇、為魚，乾為大，伏坤為郊、為國，故曰國郊。伏震為戰，乾上坎下，伏震為衛。坎為室、為廬，坎水，故曰廬漕。衛，衛侯戴公也。時狄滅衛，故暫居漕。漕，《左傳》作曹，《毛詩》作漕。</p><h3 id="噬嗑之師" tabindex="-1">噬嗑之師 <a class="header-anchor" href="#噬嗑之師" aria-label="Permalink to “噬嗑之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>龍入天關，經厯九山。登高上下，道里險難。日晏不食，絕無甘酸。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>此用《噬嗑》象。震為龍，艮為天、為關，故曰龍入天關。艮為山，震數九，故曰九山。震為登，艮為高、為上，坎為下，故曰登高上下。艮為道里，坎陷，故曰道里險難。離為日，坎為暮，故曰日晏。震為日、為食，坎憂故不食。巽為臭，巽伏不見，故絕無甘酸。</p><h3 id="噬嗑之比" tabindex="-1">噬嗑之比 <a class="header-anchor" href="#噬嗑之比" aria-label="Permalink to “噬嗑之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>沙漠北塞，絕無水泉。君子徵兇，役伕力殫。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>互艮為小石、為沙、為塞，坎北，故曰北塞。坎為水泉，艮火在下，故無水泉。艮為君子，震為徵，震覆故徵兇。坤為役，震為夫，震覆故力殫。○絕無，汲古作純無，依宋元本。力殫，宋元本作苦艱，依汲古。</p><h3 id="噬嗑之小畜" tabindex="-1">噬嗑之小畜 <a class="header-anchor" href="#噬嗑之小畜" aria-label="Permalink to “噬嗑之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>關折門啟，衿帶解墮。福與善生，憂不為禍。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>伏坎為關。關，門牡也。兌為折，乾為門，巽為帶、為解墮。乾為福、為善，故曰福與善生。坤為憂、為禍，坤伏故不禍。○生，宋元本作坐，從汲古。折，汲古作柝，從宋元本。</p><h3 id="噬嗑之履" tabindex="-1">噬嗑之履 <a class="header-anchor" href="#噬嗑之履" aria-label="Permalink to “噬嗑之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>狼虎所嗥，患害必遭。不利有為，宜以遁逃。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>乾為虎狼，兌為嗥，伏坎為患害，巽為利，兌折故不利。巽為伏，故曰遁逃。言遭遇危險，不利於進利退也。</p><h3 id="噬嗑之泰" tabindex="-1">噬嗑之泰 <a class="header-anchor" href="#噬嗑之泰" aria-label="Permalink to “噬嗑之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>金精耀怒，帶劍過午。兩虎相距，弓弩滿野，雖憂無苦。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾為金，震為耀怒。金精，虎也。《河圖帝覽嬉》&quot;月者，金之精虎&quot;，西方宿故亦為金精。《噬嗑》離為午，艮為劍、為虎，正反艮，故曰兩虎相距。艮為野，坎為憂、為弓弩。○苦，汲古作咎，依宋元本。</p><h3 id="噬嗑之否" tabindex="-1">噬嗑之否 <a class="header-anchor" href="#噬嗑之否" aria-label="Permalink to “噬嗑之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>朽根枯樹，華葉落去。卒逢火焱，相隨偃僕。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽為樹、為隕落，故曰朽根枯樹，華葉落去。艮為火焱，巽隕為偃僕。○華葉落去，依汲古本，宋元本作葉落死去。○艮為火證。</p><h3 id="噬嗑之同人" tabindex="-1">噬嗑之同人 <a class="header-anchor" href="#噬嗑之同人" aria-label="Permalink to “噬嗑之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>入暗出明，動作有光。轉運休息，常樂永康。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。坎為暗，震為出，巽為入，離為明、為光，坎隱伏，故轉運休息。震為樂。○入暗出明，從宋元，汲古本作&quot;入和出暗&quot;。永，汲古作允，依宋元本。</p><h3 id="噬嗑之大有" tabindex="-1">噬嗑之大有 <a class="header-anchor" href="#噬嗑之大有" aria-label="Permalink to “噬嗑之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>國多忌諱，大人恆畏。結口無患，可以長存。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為國，坎為忌，乾為大人，乾惕，故曰大人恆畏。坎為患，兌為口，坤閉，故曰結口。言當忌諱之時，宜括囊自守，免於患害也。</p><h3 id="噬嗑之謙" tabindex="-1">噬嗑之謙 <a class="header-anchor" href="#噬嗑之謙" aria-label="Permalink to “噬嗑之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>天地渟厚，六合光明。陰陽順序，厥功以成。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為天、為光明，坤地為厚，坎為合，數六，故曰六合。坤為順，九三陽遇陰通行無阻，故曰順序。震為功，艮為成。○厚、陰陽順序，依宋元本，汲古作亨、作陰序陽順。</p><h3 id="噬嗑之豫" tabindex="-1">噬嗑之豫 <a class="header-anchor" href="#噬嗑之豫" aria-label="Permalink to “噬嗑之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>裸裎逐狐，為人觀笑。牝雞雄晨，主作亂妖。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《鹹》。○雄晨，依宋元本，汲古作鳴晨。</p><h3 id="噬嗑之隨" tabindex="-1">噬嗑之隨 <a class="header-anchor" href="#噬嗑之隨" aria-label="Permalink to “噬嗑之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>陰升陽伏，桀失其室，相喂不食。上下卦皆陰在上、陽居下，故曰陰升陽伏。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為室，兌剛魯，故曰桀。下卦艮覆，故曰桀失其室。震為食，初至四正反震，故曰相喂，艮止故不食。○首句從宋元本，汲古作陰失陽復，非。</p><h3 id="噬嗑之蠱" tabindex="-1">噬嗑之蠱 <a class="header-anchor" href="#噬嗑之蠱" aria-label="Permalink to “噬嗑之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>蜎飛蠕動，各有配偶。大小相保，鹹得其所。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《豫》。</p><h3 id="噬嗑之臨" tabindex="-1">噬嗑之臨 <a class="header-anchor" href="#噬嗑之臨" aria-label="Permalink to “噬嗑之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>鬼守我廬，欲呼伯去。曾孫壽考，司命不許，與生相保。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤為鬼、為我，伏艮為守、為廬，震為呼、為伯，震往，故曰欲呼伯去。伏艮為曾孫、為壽，伏巽為命，震為生，故不許也。言鬼雖呼伯去，無如命本壽考，司命不許其去也。</p><h3 id="噬嗑之觀" tabindex="-1">噬嗑之觀 <a class="header-anchor" href="#噬嗑之觀" aria-label="Permalink to “噬嗑之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>禍走患伏，喜為我福。兇惡消亡，災害不作。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>伏《大壯》。坤為禍患，震為走，言陽長陰消。震為喜，乾為福，坤為兇惡、為災害，陰消故曰不作。</p><h3 id="噬嗑之噬嗑" tabindex="-1">噬嗑之噬嗑 <a class="header-anchor" href="#噬嗑之噬嗑" aria-label="Permalink to “噬嗑之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>麒麟鳳凰，善政得祥。陰陽和調，國無災殃。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>離為文，下互大離，故曰麒麟鳳凰，卦水火俱備，故曰陰陽和調。艮為國，坎為災，震樂故無災殃。</p><h3 id="噬嗑之賁" tabindex="-1">噬嗑之賁 <a class="header-anchor" href="#噬嗑之賁" aria-label="Permalink to “噬嗑之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>智不別揚，張狂妄行。蹈淵僕顛，傷殺伯身。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎水為智，震為張狂、為行、為蹈，坎為淵，震在上，故曰蹈淵，伏巽故僕顛。震為伯，艮為身，伏兌為毀折，故傷殺伯身。○狂、蹈，汲古作誑、作陷，依宋元本。</p><h3 id="噬嗑之剝" tabindex="-1">噬嗑之剝 <a class="header-anchor" href="#噬嗑之剝" aria-label="Permalink to “噬嗑之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>兇憂災殃，日益明章。禍不可救，三卻夷傷。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為兇災，艮為明、為日，坤為禍、為死，故曰夷傷、曰不可救。卻者，退也，坤消故退。正互三坤，故曰三卻。《左傳成十七年》：&quot;晉厲公殺卻至、卻錡、卻犨。○明章，依汲古，宋元本作章明。按：明與殃亦韻。救，宋元本作休，依汲古。卻，汲古訛都，依宋元本。</p><h3 id="噬嗑之復" tabindex="-1">噬嗑之復 <a class="header-anchor" href="#噬嗑之復" aria-label="Permalink to “噬嗑之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>長尾蜲蛇，畫地為河。深不可涉，絕無以北，悵然嘳息。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《鹹》。 ○蜲，同蟡。《管子水地篇》：&quot;蟡，一頭而兩身，其形若蛇，其長八尺&quot;，然則蜲蛇，二蟲名也，故曰長尾。《師》之《鹹》作委蛇。《鹹》互巽，巽為蟲，亦宜作蜲，故依此校改。第四句依汲古，宋元本作阻絕以無。噴，汲古作憤，依宋元本。</p><h3 id="噬嗑之無妄" tabindex="-1">噬嗑之無妄 <a class="header-anchor" href="#噬嗑之無妄" aria-label="Permalink to “噬嗑之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>愛我嬰女，牽引不與。冀幸高貴，反得賤下。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>通《升》。坤為我，兌為嬰女，艮手為牽引。巽為高，乾為貴，坤為賤。《無妄》皆事出意外，非所期望之事，故林辭如此。○愛，汲古訛受。反得賤下，汲古作反曰下賤，均依宋元本。</p><h3 id="噬嗑之大畜" tabindex="-1">噬嗑之大畜 <a class="header-anchor" href="#噬嗑之大畜" aria-label="Permalink to “噬嗑之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>鳧遊江湖，甘樂其餌。既不近人，雖驚不駭。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為鳧，兌為江湖，鳧在兌水上，故曰鳧遊江湖。震為餌、為甘樂、為人，艮鳧在上，故不近人。震為驚。</p><h3 id="噬嗑之頤" tabindex="-1">噬嗑之頤 <a class="header-anchor" href="#噬嗑之頤" aria-label="Permalink to “噬嗑之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>明滅光息，不能復食。精魄既喪，以夜為室。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為光明，坤黑，故息滅。震為食，坤死，故不食、故曰喪。震為精，坤為魄、為夜，艮為室。</p><h3 id="噬嗑之大過" tabindex="-1">噬嗑之大過 <a class="header-anchor" href="#噬嗑之大過" aria-label="Permalink to “噬嗑之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>奇適無偶，習靜獨處。所願不從，心思勞苦。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>奇，只也。《禮投壺》&quot;一算為奇&quot;，適，往也。奇適無偶，言獨往也。巽為寡，正覆巽相背，又陽陷陰中，故所願不從。伏坤為心、為思，坤萬物致役，故為勞苦。○偶，依元本，宋本汲古作耦。靜，宋元本作靖，依汲古。</p><h3 id="噬嗑之坎" tabindex="-1">噬嗑之坎 <a class="header-anchor" href="#噬嗑之坎" aria-label="Permalink to “噬嗑之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>葛藟蒙棘，華不得實。讒侫亂政，使忠壅塞。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《中孚》，說詩異毛。</p><h3 id="噬嗑之離" tabindex="-1">噬嗑之離 <a class="header-anchor" href="#噬嗑之離" aria-label="Permalink to “噬嗑之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>鵲笑鳩舞，來遺我酒。大喜在後，授我龜紐。龍喜張口，超拜福祉。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>離為鳩，伏震為鵲、為笑舞，故鵲笑鳩舞。伏坎為酒，震為喜、為後，故曰大喜在後。艮為遺、為授、為龜，震為龍、為口，龜紐、龍口，皆印飾。《後漢輿服志》：&quot;諸王金印龜紐&quot;，註引《漢舊儀》&quot;傳國璽盤五龍&quot;，龜紐龍口，言得印綬也。震為福祉，艮手為拜。全用伏象。○超，依汲古本，宋元本作起。</p><h3 id="噬嗑之鹹" tabindex="-1">噬嗑之鹹 <a class="header-anchor" href="#噬嗑之鹹" aria-label="Permalink to “噬嗑之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>搖尾逐災，雲沉孽除。洿泥生梁，下為田主。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為尾，伏坤為災，震為搖、為逐，坤為雲、為孽、為水、為洿泥，震為梁、為主，坤為田、為下。多用伏象。○第二句汲古作雲孽闢除，依宋元本。</p><h3 id="噬嗑之恆" tabindex="-1">噬嗑之恆 <a class="header-anchor" href="#噬嗑之恆" aria-label="Permalink to “噬嗑之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>白鶴銜珠，夜食為明。膏潤優渥，國歲年豐。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為鶴、為珠，兌口為銜、為食，兌昧為夜。乾為光明，兌水故曰膏潤優渥。乾為年歲。按：《搜神記》有鶴為弋人射傷，噲參為療養之，創愈放之，後鶴銜珠雌雄各一到門外為報。</p><h3 id="噬嗑之遯" tabindex="-1">噬嗑之遯 <a class="header-anchor" href="#噬嗑之遯" aria-label="Permalink to “噬嗑之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>內執柔德，上訟以默。守邑賴德，禍災不作。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>陰柔在下故曰內執柔德。乾為言，兌為言，而兌反與乾言相背，故曰訟。下卦艮止，故嘿爾不訟。艮為邑，乾為宗、為德，坤為災禍，坤伏故不災。○默，元本作嘿，依宋本、汲古。</p><h3 id="噬嗑之大壯" tabindex="-1">噬嗑之大壯 <a class="header-anchor" href="#噬嗑之大壯" aria-label="Permalink to “噬嗑之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>犬吠驚駭，公拔戈起。玄冥厭火，消散瓦解。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>伏艮為犬，震為吠、為驚、為公、為起，艮為戈、為拔，故曰公拔戈起。玄冥，水神。《月令》&quot;孟冬之月，其神玄冥&quot;。水克火故曰厭火。伏坤為水，艮為火，火在水上當然消散。震為瓦、為解。玄冥，北方水神，伏坤位北而地黑，故曰玄冥。</p><h3 id="噬嗑之晉" tabindex="-1">噬嗑之晉 <a class="header-anchor" href="#噬嗑之晉" aria-label="Permalink to “噬嗑之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>公悅嫗喜，子孫俱在。榮譽日登，福祿來處。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>象多未詳，或用遇卦象。</p><h3 id="噬嗑之明夷" tabindex="-1">噬嗑之明夷 <a class="header-anchor" href="#噬嗑之明夷" aria-label="Permalink to “噬嗑之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鳴哺鷇，長欲飛去。循枝上下，適與風遇。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>顛隕樹根，命不可救。離為鳥，震為鳴、為子、為食，故曰哺。鷇，小鳥也。震為長、為飛、為枝、為上，坤為下，伏巽為風、為顛隕、為樹、為命，坤死故不可救。○哺，汲古訛捕，依宋元本。</p><h3 id="噬嗑之家人" tabindex="-1">噬嗑之家人 <a class="header-anchor" href="#噬嗑之家人" aria-label="Permalink to “噬嗑之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>析薪熾酒，使媒求婦。和合齊宋，薑子悅喜。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>巽木為薪，坎為破，故析薪。坎為酒，火在下，故曰熾酒。坎為通，故曰媒。巽為婦、為齊。《說文》：&quot;以木架屋曰宋&quot;，故艮為宋。遇卦《噬嗑》互艮。薑，齊姓。子，宋姓。伏震為喜。《詩齊風》：&quot;析薪如之何，匪斧不克；娶妻如之何，匪媒不得&quot;，毛謂文薑歸魯，齊襄思之，茲曰齊宋是齊詩，不指文薑。</p><h3 id="噬嗑之睽" tabindex="-1">噬嗑之睽 <a class="header-anchor" href="#噬嗑之睽" aria-label="Permalink to “噬嗑之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>鄰不我顧，而望玉女。身多疣癩，誰當媚者。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《小過》。○我，依汲古，宋元本作可，非。而望玉女，汲古作而望至女，依宋元。</p><h3 id="噬嗑之蹇" tabindex="-1">噬嗑之蹇 <a class="header-anchor" href="#噬嗑之蹇" aria-label="Permalink to “噬嗑之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>遠視無光，不知青黃。黈纊塞耳，使君暗聾。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《噬嗑》象。艮為觀、為光，坎隱故無光。離為黃，震為青、為黃，《漢書東方朔傳》：&quot;黈纊垂耳所以塞聰&quot;，註：以黃綿為圈懸於冕之兩旁，示耳不外聽。坎為耳、為塞，故耳塞。伏巽為綿，纊黈黃色，亦震象。震為君，耳塞故暗聾。</p><h3 id="噬嗑之解" tabindex="-1">噬嗑之解 <a class="header-anchor" href="#噬嗑之解" aria-label="Permalink to “噬嗑之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>克身整己，逢禹巡狩。賜我玄圭，蒙福受佑。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>艮為身，艮覆，故曰克身。震為王、為禹，為巡狩、為玉、為玄黃，故曰玄圭。又為福祉。○整己，依汲古，宋元本作己整。佑，依汲古，宋元本作祉，上聲，與狩不協。</p><h3 id="噬嗑之損" tabindex="-1">噬嗑之損 <a class="header-anchor" href="#噬嗑之損" aria-label="Permalink to “噬嗑之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>遠望千里，不見黑子。離婁之明，無盈於光。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤為千里，艮為望，震為子，坤黑故曰黑子，坤閉故不見。離為光明，互大離，故曰離婁。離婁，古明目人，見孟子。</p><h3 id="噬嗑之益" tabindex="-1">噬嗑之益 <a class="header-anchor" href="#噬嗑之益" aria-label="Permalink to “噬嗑之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>斧斤所斫，瘡痏不息。針石不施，下即空室。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>伏兌為斧，艮手為斫、為節、為瘡痏、為石、為室，坤死，故曰下即空室。</p><h3 id="噬嗑之夬" tabindex="-1">噬嗑之夬 <a class="header-anchor" href="#噬嗑之夬" aria-label="Permalink to “噬嗑之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>南國少子，才略美好。求我長女，賤薄不與。反得醜陋，後乃大悔。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《漸》。南國，依校改，各本作齊侯，非。此以乾為南之證。</p><h3 id="噬嗑之姤" tabindex="-1">噬嗑之姤 <a class="header-anchor" href="#噬嗑之姤" aria-label="Permalink to “噬嗑之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>失儷後旅，天門地戶。不知所在，安止無咎。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>巽與震為儷偶、為伴旅，巽寡，故失儷後旅。《內經》：&quot;乾居西北，為天門，巽居東南，為地戶&quot;，巽進退，故不知所在。懼陰消陽，故安止無咎。</p><h3 id="噬嗑之萃" tabindex="-1">噬嗑之萃 <a class="header-anchor" href="#噬嗑之萃" aria-label="Permalink to “噬嗑之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>烏孫氏女，深目黑醜。嗜慾不同，過時無偶。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為孫、為黔，故曰烏孫。兌為女，伏大離，故曰深目。坤為黑、為醜，艮為時，巽寡，故無偶。</p><h3 id="噬嗑之升" tabindex="-1">噬嗑之升 <a class="header-anchor" href="#噬嗑之升" aria-label="Permalink to “噬嗑之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>伯駕純騮，南至東萊。求索車馬，道闕中止。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為伯、為駕、為馬。純，黑也，坤為黑，故曰純騮。震為南，又為東、為草莽，故曰東萊，山名。坤為車、為馬，伏艮為求、為道、為止。○伯，宋元本作叔，闕作悅，依汲古。萊，汲古作華，依宋元本。車，宋元本作駒，依汲古。</p><h3 id="噬嗑之困" tabindex="-1">噬嗑之困 <a class="header-anchor" href="#噬嗑之困" aria-label="Permalink to “噬嗑之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>二女寶珠，誤鄭大夫。交父無禮，自為作笑。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>丁雲：《初學記》引《韓詩》：&quot;鄭交甫過漢皋，遇二女佩兩珠，交甫索其珠，二女與之，去十步亡矣&quot;，故曰誤。兌為女，卦數二，故曰二女。伏震為珠、為夫，坎為鄭，震為父、為笑，言交甫無禮於二女，致招笑侮，由自取也。○交，宋元、汲古皆作君，依王先謙校。</p><h3 id="噬嗑之井" tabindex="-1">噬嗑之井 <a class="header-anchor" href="#噬嗑之井" aria-label="Permalink to “噬嗑之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>陽城太室，神明所息。仁智之居，獨無兵革。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《蒙》。伏震為仁，坎為智。○仁智之居，依宋元本，汲古作仁者之君，非。</p><h3 id="噬嗑之革" tabindex="-1">噬嗑之革 <a class="header-anchor" href="#噬嗑之革" aria-label="Permalink to “噬嗑之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>大蛇為殃，使道不通。歲收尠少，年榖敗傷。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>巽為蛇，乾大，故曰大蛇。伏震為道路，坤閉故不通。《史記》：&quot;高祖夜徑澤中，有大蛇當徑&quot;是也。乾為歲，巽隕落，故歲收鮮少，故年榖傷。巽為榖也。○歲收，依汲古，宋元本作歲露。尠，依宋元本，舊註雲音鮮，汲古作甚，非。</p><h3 id="噬嗑之鼎" tabindex="-1">噬嗑之鼎 <a class="header-anchor" href="#噬嗑之鼎" aria-label="Permalink to “噬嗑之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>三足孤烏，靈明為御。司過罰惡，自殘其家，毀敗為憂。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《坎》之《渙》。此以離為烏，伏震為足。</p><h3 id="噬嗑之震" tabindex="-1">噬嗑之震 <a class="header-anchor" href="#噬嗑之震" aria-label="Permalink to “噬嗑之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>車雖駕，兩靷絕。馬欲步，雙輪脫。行不至，道遇害。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為車、為駕，伏巽為靷，巽隕故絕。震為馬、為步，互坎為輪，伏兌卦，數二，故曰兩靷、曰雙輪。震為行、為道，坎為害。○無輪明刊、清刊各本皆刪去雖字、不字，作為四字句，而汲古本下註一本作云云，仍按原文改竄成四字句尤為妄謬，茲依宋元本。</p><h3 id="噬嗑之艮" tabindex="-1">噬嗑之艮 <a class="header-anchor" href="#噬嗑之艮" aria-label="Permalink to “噬嗑之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>鬱映不明，為陰所傷。眾霧集聚，共奪日光。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為明，坎黑，三上皆乘重陰，故曰鬱映不明。映，日食色也。坎為眾、為雲霧、為積，離日伏，故奪日光。○映，依汲古，宋元本作怏。集聚，依宋元，汲古作麗集，映音決。</p><h3 id="噬嗑之漸" tabindex="-1">噬嗑之漸 <a class="header-anchor" href="#噬嗑之漸" aria-label="Permalink to “噬嗑之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>鸋鴂鴟梟，治成遇災。周公勤勞，綏德安家。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，故曰鸋鴂。鴟鴞，《豳風》周公貽成王詩也。坎為災，伏震為周、為公，坎為勞，艮為家。按：《毛傳》鴟鴞，鸋鴂也，以喻管蔡，此作鴟梟，梟鴞同。梟長大食母，故曰治成遇災，言其母養成而遇害也。此與《韓詩》說合，《韓詩》鴟鴞所以愛其子者，適以病之，正以喻成王也。疑較毛傳訓切。○鸋，依宋本，汲古作鸇，非。治成，元本、汲古皆作治城，依宋本。遇災，宋元本、汲古皆作御災，依局本。</p><h3 id="噬嗑之歸妹" tabindex="-1">噬嗑之歸妹 <a class="header-anchor" href="#噬嗑之歸妹" aria-label="Permalink to “噬嗑之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>名成德就，項領不試。景公耄老，尼父逝去。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《剝》。</p><h3 id="噬嗑之豐" tabindex="-1">噬嗑之豐 <a class="header-anchor" href="#噬嗑之豐" aria-label="Permalink to “噬嗑之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>一夫兩心，歧刺不深。所以無功，求事不成。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《臨》。○歧，宋元本作岐，依汲古。歧，尖也。《後漢張湛傳》&quot;麥秀兩歧&quot;是其證。又隴上記：&quot;狄梁公墓棘直而不歧&quot;，言不尖也。</p><h3 id="噬嗑之旅" tabindex="-1">噬嗑之旅 <a class="header-anchor" href="#噬嗑之旅" aria-label="Permalink to “噬嗑之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>羿張烏號，彀射天狼。柱國雄勇，敗於滎陽。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>羿，古之善射者。《論語》曰羿善射是也。烏號，弓名。天狼，星名。《淮南子》：&quot;堯時十日並出，命羿射之，落其九&quot;，此雲射天狼與《淮南子》異，《史記陳涉世家》：&quot;以房君蔡賜為柱國，後戰死而不著其處&quot;。柱，各本皆作趙，惟丁晏釋文作柱，恐趙國是人名，今姑依丁本。兌剛魯故曰羿。離為烏，兌為號，艮為天、為狼、為星、為柱、為國，兌為雄勇、為毀折，故敗。滎，水名，伏坎為水。○柱，宋元、汲古作趙，依丁本。滎，元本訛榮，依宋、汲古本。</p><h3 id="噬嗑之巽" tabindex="-1">噬嗑之巽 <a class="header-anchor" href="#噬嗑之巽" aria-label="Permalink to “噬嗑之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>東家殺牛，汙穢腥臊。神背西顧，命衰絕周。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>互離為東、為牛，伏艮為家，兌毀折，故曰殺。巽為臭，故曰腥臊。伏震為神，艮為背，互兌為西，離為顧，巽為命、為衰絕，伏震為周。神背西顧者，言神背東鄰紂，西顧於周。命衰絕周者，言殷命衰歇而絕於周也。義本《既濟九五》爻詞，蓋漢儒說多如此，然實非也。○穢，汲古作臭，背作皆，依宋元。衰絕，宋元本作絕衰，依汲古。</p><h3 id="噬嗑之兌" tabindex="-1">噬嗑之兌 <a class="header-anchor" href="#噬嗑之兌" aria-label="Permalink to “噬嗑之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>火起吾後，喜炙我廡。蒼龍銜水，泉噀屋柱，雖憂無咎。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。艮為火，震為起、為後，故曰火起我後。震為喜、為口、為蒼龍、為銜，坎為水，水泉。艮為屋、為柱，坎為憂，言火雖近，以龍銜水噀灑屋柱而無咎也。○吾後，汲古作我後，憂作難，均依宋元本。我廡，宋元本訛我鹿，汲古作吾廬，依《既濟》之《恆》校。屋柱，宋元作柱屋，期與鹿韻，尤非，依汲古。</p><h3 id="噬嗑之渙" tabindex="-1">噬嗑之渙 <a class="header-anchor" href="#噬嗑之渙" aria-label="Permalink to “噬嗑之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>桃雀竊脂，巢於小枝。搖動不安，為風所吹。寒心慄慄，常憂殆危。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《遯》。○慄慄，汲古作飄搖，依宋元本。殆危，宋元本作不殆，依汲古。桃雀，既桃蟲，《毛詩》註：鷦鷯也。</p><h3 id="噬嗑之節" tabindex="-1">噬嗑之節 <a class="header-anchor" href="#噬嗑之節" aria-label="Permalink to “噬嗑之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>徙足去域，飛入東國。有所畏避，深藏遠匿。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為足、為去、為飛、為東，艮為域、為國，坎為畏避、為藏匿。○徙，汲古作徒，依宋元本。遠，宋元作隱，依汲古。</p><h3 id="噬嗑之中孚" tabindex="-1">噬嗑之中孚 <a class="header-anchor" href="#噬嗑之中孚" aria-label="Permalink to “噬嗑之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>瓊英朱草，仁政得道。鳧鷖在渚，福祿來下。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>《齊詩》：&quot;尚之以瓊英乎&quot;，而箋瓊英，猶瓊華也。元本註朱草，百草之精王者，德盛則生。互震為英、為草、為玉，艮納丙，色赤，故曰朱草。艮為道，震為仁、為福祿，艮為鳥、為鳧鷖。三四句《小雅》詩語。○瓊，依宋元本，汲古作璚。</p><h3 id="噬嗑之小過" tabindex="-1">噬嗑之小過 <a class="header-anchor" href="#噬嗑之小過" aria-label="Permalink to “噬嗑之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>陳蔡之厄，從者飢罷。明德上通，憂不為兇。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為陳、為蔡、為從，互大坎為厄、為勞，故曰飢罷。艮為明，震為通，坎為憂兇，震出，故不憂兇。○罷，音婆，依宋元本，汲古作瘦。厄，依汲古，宋元本作危，亦非。《論語》：&quot;子厄於陳蔡，從者病，莫能興&quot;。</p><h3 id="噬嗑之既濟" tabindex="-1">噬嗑之既濟 <a class="header-anchor" href="#噬嗑之既濟" aria-label="Permalink to “噬嗑之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>春桃生華，季女宜家。受福多年，男為邦君。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《坤》。</p><h3 id="噬嗑之未濟" tabindex="-1">噬嗑之未濟 <a class="header-anchor" href="#噬嗑之未濟" aria-label="Permalink to “噬嗑之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>徑邪賊田，政惡傷民。夫婦咒詛，泰山覆顛。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>艮為徑、為田，坎為邪、為賊，徑邪則侵田，故曰賊田。坎為傷、為眾、為民、為惡，政惡虐民，故曰傷民。坎夫離婦，離兩兌口相對，故曰咒詛。艮為山，巽下斷，故覆顛。多取半象。○泰山，依汲古，宋元本作太山，似非。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
